def check_forbidden_packages(venue_slug: str, paper_dir: Path | str) -> list[dict]:
    """Check .tex files in *paper_dir* for packages forbidden by *venue_slug*.

    Returns a list of ``{kind, message, location}`` dicts (same shape as
    ``figure_check`` findings).  Empty list when no venue config, no
    forbidden packages, or no violations.
    """
    cfg = load_venue_typesetting(venue_slug)
    if not cfg:
        return []

    forbidden = set(cfg.get("forbidden_packages", []))
    if not forbidden:
        return []

    paper_dir = Path(paper_dir)
    issues: list[dict] = []

    for tex in sorted(paper_dir.glob("*.tex")):
        try:
            content = tex.read_text(errors="replace")
        except OSError:
            continue
        clean = _COMMENT_RE.sub("", content)
        for line_no, line in enumerate(clean.splitlines(), 1):
            for m in _USEPACKAGE_RE.finditer(line):
                pkgs = [p.strip() for p in m.group(1).split(",")]
                for pkg in pkgs:
                    if pkg in forbidden:
                        issues.append({
                            "kind": "forbidden_package",
                            "message": f"Package '{pkg}' is forbidden by {venue_slug}",
                            "location": f"{tex.name}:{line_no}",
                        })

    return issues

class CompiledPaper:
    """Result of running the LaTeX compiler on a paper directory.

    `pdf_path` is None on failure. `log_tail` is the last ~80 lines of the
    .log so failures are debuggable without slurping the whole log into the
    agent's context.
    """
    success: bool
    pdf_path: Path | None
    paper_dir: Path
    main_tex: str
    log_tail: str = ""
    error: str = ""
    pages: int | None = None
    warnings: list[str] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return {
            "success": self.success,
            "pdf_path": str(self.pdf_path) if self.pdf_path else None,
            "paper_dir": str(self.paper_dir),
            "main_tex": self.main_tex,
            "log_tail": self.log_tail,
            "error": self.error,
            "pages": self.pages,
            "warnings": list(self.warnings),
        }


def dumps(obj: Any) -> str:
    """JSON-serialize a writing dataclass (or list of) for MCP transport."""
    if isinstance(obj, list):
        return json.dumps([_to_jsonable(x) for x in obj], ensure_ascii=False)
    return json.dumps(_to_jsonable(obj), ensure_ascii=False)


def _to_jsonable(obj: Any) -> Any:
    if hasattr(obj, "to_dict"):
        return obj.to_dict()
    if isinstance(obj, Path):
        return str(obj)
    if isinstance(obj, dict):
        return {k: _to_jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [_to_jsonable(x) for x in obj]
    return obj

